import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import BookingTile from "../../components/common/BookingTile";
import salonImage from "../../images/oliviaSalon.jpg"; // example image

// ---- Styled Components ----
const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 40px 0;
  margin-left: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start; /* ✅ forces all children (BookingTile) to start on left */
  gap: 60px;
`;

const Section = styled.div`
  width: 100%;
`;

const SectionTitle = styled.h2`
  font-family: "Inter", sans-serif;
  font-size: 36px;
  font-weight: 800;
  color: #27374d;
  margin-bottom: 25px;
`;

const TilesContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 25px;
`;

// ---- Popup styled ----
const Overlay = styled.div`
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999;
`;

const PopupBox = styled.div`
  width: 420px;
  max-width: 90%;
  background: #ffffff;
  border-radius: 16px;
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
`;

const PopupTitle = styled.h3`
  margin: 0;
  font-size: 22px;
  font-weight: 800;
  color: #27374d;
`;

const PopupRow = styled.div`
  display: flex;
  flex-direction: column;
  gap: 6px;
`;

const Label = styled.label`
  font-size: 14px;
  font-weight: 600;
  color: #27374d;
`;

const Input = styled.input`
  width: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid #d0d0d0;
  font-size: 14px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid #d0d0d0;
  font-size: 14px;
`;

const PopupFooter = styled.div`
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 8px;
`;

const Button = styled.button<{ variant?: "primary" | "ghost" }>`
  padding: 8px 16px;
  border-radius: 999px;
  border: ${(p) => (p.variant === "ghost" ? "1px solid #d0d0d0" : "none")};
  background: ${(p) => (p.variant === "primary" ? "#27374d" : "#ffffff")};
  color: ${(p) => (p.variant === "primary" ? "#ffffff" : "#27374d")};
  font-size: 14px;
  cursor: pointer;
`;

// ---- Types ----
type BookingStatus = "upcoming" | "past";

type BookingItem = {
  id: number;
  date: string; // display string
  startTime?: string; // ISO string for real usage
  businessId?: string; // needed for API
  image: string;
  salonName: string;
  location: string;
  services: string[];
  status: BookingStatus;
};

// Staff type from API
type AvailableStaff = {
  index: number;
  fullName: string;
  role?: string;
};

// ---- Component ----
const BookingsPage: React.FC = () => {
  console.log("✅ BookingsPage rendered");

  // Dummy data – later replace with API data
  const [upcomingBookings] = useState<BookingItem[]>([
    {
      id: 1,
      date: "Sep 10, 2024 - 9:30 AM",
      startTime: "2024-09-10T09:30", // example ISO for API
      businessId: "BUSINESS_ID_1", // replace when wired to backend
      image: salonImage,
      salonName: "Hair Avenue",
      location: "Lakewood, California",
      services: ["Hair Cut", "Hair Wash"],
      status: "upcoming",
    },
  ]);

  const [pastBookings] = useState<BookingItem[]>([
    {
      id: 2,
      date: "Sep 5, 2024 - 11:30 AM",
      startTime: "2024-09-05T11:30",
      businessId: "BUSINESS_ID_2",
      image: salonImage,
      salonName: "CL Salon",
      location: "Lakewood, California",
      services: ["Hair Cut", "Hair Wash"],
      status: "past",
    },
    {
      id: 3,
      date: "Aug 15, 2024 - 9:00 AM",
      startTime: "2024-08-15T09:00",
      businessId: "BUSINESS_ID_3",
      image: salonImage,
      salonName: "Mcolors Beauty Salon",
      location: "Lakewood, California",
      services: ["Hair Cut", "Hair Wash"],
      status: "past",
    },
  ]);

  // ---- Staff selection popup state ----
  const [showPopup, setShowPopup] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState<BookingItem | null>(
    null
  );
  const [selectedDateTime, setSelectedDateTime] = useState("");
  const [availableStaff, setAvailableStaff] = useState<AvailableStaff[]>([]);
  const [selectedStaffIndex, setSelectedStaffIndex] = useState<number | "">("");
  const [loadingStaff, setLoadingStaff] = useState(false);
  const [staffError, setStaffError] = useState<string | null>(null);

  const openReschedulePopup = (booking: BookingItem) => {
    setSelectedBooking(booking);
    setSelectedDateTime("");
    setAvailableStaff([]);
    setSelectedStaffIndex("");
    setStaffError(null);
    setShowPopup(true);
  };

  const closePopup = () => {
    setShowPopup(false);
    setSelectedBooking(null);
    setSelectedDateTime("");
    setAvailableStaff([]);
    setSelectedStaffIndex("");
    setStaffError(null);
  };

  // 🔁 Fetch available staff whenever user selects date & time
  useEffect(() => {
    const fetchAvailableStaff = async () => {
      if (!showPopup || !selectedBooking || !selectedDateTime) return;
      if (!selectedBooking.businessId) return; // safety for dummy data

      setLoadingStaff(true);
      setStaffError(null);

      try {
        const token = localStorage.getItem("customerToken");

        const res = await fetch(
          `http://localhost:5000/api/bookings/available-staff?businessId=${
            selectedBooking.businessId
          }&startTime=${encodeURIComponent(selectedDateTime)}`,
          {
            headers: {
              "Content-Type": "application/json",
              ...(token ? { Authorization: `Bearer ${token}` } : {}),
            },
          }
        );

        const data = await res.json();

        if (!res.ok) {
          throw new Error(data.message || "Failed to load staff");
        }

        setAvailableStaff(data.staff || []);
        setSelectedStaffIndex("");
      } catch (err: any) {
        console.error(err);
        setAvailableStaff([]);
        setStaffError(err.message || "Failed to load staff");
      } finally {
        setLoadingStaff(false);
      }
    };

    fetchAvailableStaff();
  }, [showPopup, selectedBooking, selectedDateTime]);

  const handleConfirmReschedule = () => {
    if (!selectedBooking) return;

    if (!selectedDateTime) {
      alert("Please choose a new date and time.");
      return;
    }

    if (selectedStaffIndex === "") {
      alert("Please choose a staff member.");
      return;
    }

    // 🔧 TODO: call backend API to actually reschedule:
    // e.g. POST /api/bookings/reschedule with { bookingId, newStartTime, staffIndex }
    alert(
      `✅ Booking #${selectedBooking.id} rescheduled to ${selectedDateTime} with staff index ${selectedStaffIndex}`
    );

    closePopup();
  };

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        <Section>
          <SectionTitle>Upcoming Bookings</SectionTitle>
          <TilesContainer>
            {upcomingBookings.map((booking) => (
              <BookingTile
                key={booking.id}
                {...booking}
                onCancel={() => alert(`Cancelled booking ${booking.id}`)}
                onViewReceipt={() =>
                  alert(`View receipt for ${booking.id}`)
                }
                onReschedule={() => openReschedulePopup(booking)}
              />
            ))}
          </TilesContainer>
        </Section>

        <Section>
          <SectionTitle>Past Bookings</SectionTitle>
          <TilesContainer>
            {pastBookings.map((booking) => (
              <BookingTile
                key={booking.id}
                {...booking}
                onLeaveRating={() =>
                  alert(`Leave rating for ${booking.id}`)
                }
                onViewReceipt={() =>
                  alert(`View receipt for ${booking.id}`)
                }
              />
            ))}
          </TilesContainer>
        </Section>
      </ContentWrapper>

      {/* ---- Reschedule + Select Staff Popup ---- */}
      {showPopup && selectedBooking && (
        <Overlay onClick={closePopup}>
          <PopupBox onClick={(e) => e.stopPropagation()}>
            <PopupTitle>Reschedule Booking</PopupTitle>

            <PopupRow>
              <span style={{ fontSize: 14 }}>
                <strong>{selectedBooking.salonName}</strong>
                <br />
                {selectedBooking.services.join(", ")}
              </span>
            </PopupRow>

            <PopupRow>
              <Label>New Date &amp; Time</Label>
              <Input
                type="datetime-local"
                value={selectedDateTime}
                onChange={(e) => setSelectedDateTime(e.target.value)}
              />
            </PopupRow>

            <PopupRow>
              <Label>Select Staff</Label>

              {loadingStaff && (
                <span style={{ fontSize: 13 }}>Loading staff...</span>
              )}

              {staffError && (
                <span style={{ fontSize: 13, color: "red" }}>
                  {staffError}
                </span>
              )}

              {!loadingStaff && !staffError && selectedDateTime && (
                <>
                  {availableStaff.length === 0 ? (
                    <span style={{ fontSize: 13 }}>
                      No staff available at this time.
                    </span>
                  ) : (
                    <Select
                      value={selectedStaffIndex}
                      onChange={(e) =>
                        setSelectedStaffIndex(
                          e.target.value === ""
                            ? ""
                            : Number(e.target.value)
                        )
                      }
                    >
                      <option value="">Choose staff</option>
                      {availableStaff.map((staff) => (
                        <option key={staff.index} value={staff.index}>
                          {staff.fullName}
                          {staff.role ? ` - ${staff.role}` : ""}
                        </option>
                      ))}
                    </Select>
                  )}
                </>
              )}
            </PopupRow>

            <PopupFooter>
              <Button variant="ghost" onClick={closePopup}>
                Cancel
              </Button>
              <Button variant="primary" onClick={handleConfirmReschedule}>
                Confirm
              </Button>
            </PopupFooter>
          </PopupBox>
        </Overlay>
      )}
    </PageWrapper>
  );
};

export default BookingsPage;
